// Des: Tests for ru-apiz-prob: M8 gate, shells stored via free API
// Flo: mock site + mock vendor > ladder fetch of shell pages > assert $0, kinds, caps, robots, climb
// I/O: mock responses > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const ladd = @import("ru-tier-ladd.zig"); const apiz = @import("ru-apiz-prob.zig"); const inde = @import("st-page-inde.zig"); const pipe = @import("ru-page-fetc.zig"); const vmoc = @import("nt-vend-mock.zig"); const mock = @import("te-mock-serv.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
const Rigg = struct { tmpz: std.testing.TmpDir, srv2: mock.Mock, vmkz: vmoc.Mock, dirz: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, ladz: ladd.Ladd,
pub fn upzz(self: *Rigg, conf: cfgz.Conf) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); try self.srv2.sta2(std.testing.io); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.vmkz = vmoc.Mock.init(allo); self.ladz = .{ .gpaz = allo, .iozz = std.testing.io, .conf = conf, .dbzz = &self.dbzz, .dirz = self.dirz, .back = self.vmkz.bac2(), .priv = true }; }
pub fn down(self: *Rigg) void { self.vmkz.deinit(); self.aren.deinit(); self.dbzz.close(); self.srv2.halt(); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn gozz(self: *Rigg, path: []const u8) !pipe.Outc { var buf4: [64]u8 = undefined; return ladd.laddFetc(&self.ladz, self.aren.allocator(), self.srv2.urlzOfzz(&buf4, path)); }
pub fn reco(self: *Rigg, path: []const u8) !?inde.Reco { var buf4: [64]u8 = undefined; return inde.recoGetz(&self.dbzz, self.aren.allocator(), self.srv2.urlzOfzz(&buf4, path)); } };
fn rich() cfgz.Conf { var conf: cfgz.Conf = .{}; conf.vend_free_cred = .{ .deco = 100, .zenr = 100, .brig = 100 }; return conf; }
fn fre2(rig3: *Rigg, out2: pipe.Outc) !void { try std.testing.expectEqualStrings("new", out2.stat); try std.testing.expectEqual(@as(i64, 1), out2.tier); try std.testing.expectEqual(@as(u32, 0), out2.cred); try std.testing.expectEqual(@as(u64, 0), out2.micr); try std.testing.expectEqual(@as(usize, 0), rig3.vmkz.cal3.items.len); }
test "spa shell: /api/ string found in the script, stored as json at $0" { var rig3: Rigg = undefined; try rig3.upzz(rich()); defer rig3.down(); const out2 = try rig3.gozz("/spa"); try fre2(&rig3, out2); try std.testing.expectEqualStrings("json", out2.kind); const recz = (try rig3.reco("/spa")).?; try std.testing.expectEqualStrings("json", recz.kind); try std.testing.expect(std.mem.indexOf(u8, recz.body, "Acme Widgets Alpha") != null); }
test "wordpress shell: api.w.org link leads to wp-json posts at $0" { var rig3: Rigg = undefined; try rig3.upzz(rich()); defer rig3.down(); const out2 = try rig3.gozz("/wpjson"); try fre2(&rig3, out2); try std.testing.expectEqualStrings("json", out2.kind); }
test "next shell: buildId data URL at $0" { var rig3: Rigg = undefined; try rig3.upzz(rich()); defer rig3.down(); const out2 = try rig3.gozz("/nextdata"); try fre2(&rig3, out2); try std.testing.expectEqualStrings("json", out2.kind); const recz = (try rig3.reco("/nextdata")).?; try std.testing.expect(std.mem.indexOf(u8, recz.body, "Next Gizmos list") != null); }
test "iframe shell: the frame page is stored under the host URL at $0" { var rig3: Rigg = undefined; try rig3.upzz(rich()); defer rig3.down(); const out2 = try rig3.gozz("/iframe"); try fre2(&rig3, out2); try std.testing.expectEqualStrings("text", out2.kind); const recz = (try rig3.reco("/iframe")).?; try std.testing.expect(std.mem.indexOf(u8, recz.body, "Frame content sentence") != null); }
test "shell with no json anywhere still climbs, straight to render (plain skipped)" { var rig3: Rigg = undefined; try rig3.upzz(rich()); defer rig3.down(); const out2 = try rig3.gozz("/spanone"); try std.testing.expectEqual(@as(i64, 3), out2.tier); try std.testing.expectEqual(@as(usize, 1), rig3.vmkz.cal3.items.len); try std.testing.expect(rig3.vmkz.cal3.items[0].mode == .rend); }
test "robots-disallowed probe is never sent: ladder climbs instead" { var rig3: Rigg = undefined; try rig3.upzz(rich()); defer rig3.down(); const out2 = try rig3.gozz("/spapriv"); try std.testing.expect(out2.tier >= 3); try std.testing.expect(!std.mem.eql(u8, out2.kind, "json")); try std.testing.expectEqual(@as(usize, 1), rig3.vmkz.cal3.items.len); }
test "valid JSON that shares no words with the page is rejected, ladder climbs" { var rig3: Rigg = undefined; try rig3.upzz(rich()); defer rig3.down(); const out2 = try rig3.gozz("/spaoff"); try std.testing.expect(out2.tier >= 3); try std.testing.expect(!std.mem.eql(u8, out2.kind, "json")); }
test "probe requests are capped by apiz_prob_maxz" { var conf = rich(); conf.apiz_prob_maxz = 3; var rig3: Rigg = undefined; try rig3.upzz(conf); defer rig3.down(); const out2 = try rig3.gozz("/spamany"); try std.testing.expect(out2.tier >= 3); try std.testing.expect(rig3.srv2.hits.load(.monotonic) <= 1 + 1 + 3); }
test "apiz_prob_enab=false skips probing entirely" { var conf = rich(); conf.apiz_prob_enab = false; var rig3: Rigg = undefined; try rig3.upzz(conf); defer rig3.down(); const out2 = try rig3.gozz("/spa"); try std.testing.expect(out2.tier >= 3); try std.testing.expectEqual(@as(u32, 1), rig3.srv2.hits.load(.monotonic)); }
test "winning kind is cached per host" { var rig3: Rigg = undefined; try rig3.upzz(rich()); defer rig3.down(); _ = try rig3.gozz("/spa"); const kind = (try apiz.apizGetz(&rig3.dbzz, rig3.aren.allocator(), "127.0.0.1")).?; try std.testing.expectEqualStrings("scri", kind); }
test "a vendor render is not sent when the free API works (no spend recorded)" { var rig3: Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); const out2 = try rig3.gozz("/spa"); try std.testing.expectEqual(@as(i64, 1), out2.tier); try std.testing.expectEqualStrings("json", out2.kind); }
